<script lang="ts">
  import { tower } from '../stores/tower.svelte.ts';
  import TowerAscentMemoryContent from './tower/TowerAscentMemoryContent.svelte';
  import TowerBatchContent from './tower/TowerBatchContent.svelte';
  import TowerRelicAutoContent from './tower/TowerRelicAutoContent.svelte';
  import TowerSubwayContent from './tower/TowerSubwayContent.svelte';
  import TowerChampionsContent from './tower/TowerChampionsContent.svelte';

  let snap = $derived(tower.snapshot);
  let activePanel = $state<'tower' | 'subway' | 'champions'>('tower');

  const hasExtraTabs = $derived(snap.subwayTabVisible || snap.championsTabVisible);

  $effect(() => {
    if (!snap.subwayTabVisible && activePanel === 'subway') {
      activePanel = snap.championsTabVisible ? 'champions' : 'tower';
    }
    if (!snap.championsTabVisible && activePanel === 'champions') {
      activePanel = 'tower';
    }
  });
</script>

<!-- Cible = #towerTab -->
{#if hasExtraTabs}
  <div class="tower-subtab-row">
    <button
      type="button"
      class="tower-subtab-btn"
      class:active={activePanel === 'tower'}
      data-action="switchTowerPanel"
      data-arg="tower"
      onclick={() => { activePanel = 'tower'; }}
    >{snap.titleLabel}</button>
    {#if snap.subwayTabVisible}
      <button
        type="button"
        class="tower-subtab-btn"
        class:active={activePanel === 'subway'}
        data-action="switchTowerPanel"
        data-arg="subway"
        onclick={() => { activePanel = 'subway'; }}
      >{snap.subwayTitleLabel}</button>
    {/if}
    {#if snap.championsTabVisible}
      <button
        type="button"
        class="tower-subtab-btn"
        class:active={activePanel === 'champions'}
        data-action="switchTowerPanel"
        data-arg="champions"
        onclick={() => { activePanel = 'champions'; }}
      >{snap.championsTitleLabel}</button>
    {/if}
  </div>
{/if}

{#if activePanel === 'champions' && snap.championsTabVisible}
  <div class="tower-shared-tickets-bar">
    <img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/crown-pass.png" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">
    <span>{snap.ticketsLabel}</span>
    <strong id="combatTickets">{snap.combatTickets}</strong>
  </div>
  <TowerChampionsContent />
{:else if activePanel === 'subway' && snap.subwayTabVisible}
  <TowerSubwayContent />
{:else}
  <span id="towerTitleLabel" class="sr-only">{snap.titleLabel}</span>

  <div class="tower-main-wrapper">
    <!-- Rangée compacte de 3 KPI : Tickets, Record, Marques -->
    <div class="tower-kpi-grid">
      <div class="tower-kpi-card tower-kpi-tickets" title={snap.ticketsLabel || 'Tickets de Combat'}>
        <div class="tower-kpi-header">
          <img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/crown-pass.png" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">
          <span id="towerTicketsLabel" class="tower-kpi-label">Tickets</span>
        </div>
        <div class="tower-kpi-value-row">
          <strong id="combatTickets" class="tower-kpi-value">{snap.combatTickets}</strong>
        </div>
      </div>

      <div class="tower-kpi-card tower-kpi-record" title={snap.recordLabel || 'Record Personnel'}>
        <div class="tower-kpi-header">
          <span class="tower-kpi-icon" aria-hidden="true">🗼</span>
          <span id="towerRecordLabel" class="tower-kpi-label">Record</span>
        </div>
        <div class="tower-kpi-value-row">
          <span class="tower-kpi-prefix">{snap.language === 'en' ? 'Floor' : 'Étage'}</span>
          <strong id="towerRecord" class="tower-kpi-value">{snap.towerRecord}</strong>
        </div>
      </div>

      <div class="tower-kpi-card tower-kpi-marks" title={snap.marksLabel || 'Marques du Triomphe'}>
        <div class="tower-kpi-header">
          <img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png" class="marque-triomphe-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">
          <span id="towerMarksLabel" class="tower-kpi-label">Marques</span>
        </div>
        <div class="tower-kpi-value-row">
          <strong id="triumphMarks" class="tower-kpi-value">{snap.triumphMarks}</strong>
        </div>
      </div>
    </div>

    {#if snap.towerQuestObjective}
      {@const progressPct = snap.towerQuestTarget && snap.towerQuestRemaining != null
        ? Math.min(100, Math.max(0, Math.round(((snap.towerQuestTarget - snap.towerQuestRemaining) / snap.towerQuestTarget) * 100)))
        : null}
      <div class="tower-quest-banner" role="status" aria-label={snap.towerQuestObjective}>
        <div class="tower-quest-banner__content">
          <span class="tower-quest-banner__label">
            {snap.language === 'en' ? 'Quest Objective' : 'Objectif Quête'}
          </span>
          <span class="tower-quest-banner__sep" aria-hidden="true">:</span>
          {#if snap.towerQuestTarget != null && snap.towerQuestRemaining != null}
            <span class="tower-quest-banner__target">
              {snap.language === 'en' ? 'Floor' : 'Étage'} <strong class="tower-quest-banner__value">{snap.towerQuestTarget}</strong>
            </span>
            <span class="tower-quest-banner__sep" aria-hidden="true">·</span>
            <span class="tower-quest-banner__remaining">
              {#if snap.towerQuestRemaining === 0}
                <span class="tower-quest-banner__done">{snap.language === 'en' ? 'Goal reached!' : 'Objectif atteint !'}</span>
              {:else if snap.language === 'en'}
                <span><strong class="tower-quest-banner__value">{snap.towerQuestRemaining}</strong> {snap.towerQuestRemaining > 1 ? 'floors left' : 'floor left'}</span>
              {:else}
                <span>reste <strong class="tower-quest-banner__value">{snap.towerQuestRemaining}</strong> {snap.towerQuestRemaining > 1 ? 'étages' : 'étage'}</span>
              {/if}
            </span>
          {:else}
            <span class="tower-quest-banner__text">{snap.towerQuestObjective}</span>
          {/if}
        </div>
        {#if progressPct != null}
          <div class="tower-quest-banner__bar" title="{progressPct}%">
            <div class="tower-quest-banner__bar-fill" style="width: {progressPct}%"></div>
          </div>
        {/if}
      </div>
    {/if}

    <!-- Bouton de lancement avec états et sous-titre explicite -->
    <button
      id="towerStartBtn"
      class="btn btn-save tower-start-btn"
      class:is-short={snap.startState === 'short'}
      data-state={snap.startState}
      data-action="startTowerRun"
      disabled={snap.startDisabled}
      style={snap.startState === 'short' ? `--fill-ratio: ${(snap.startFillRatio * 100).toFixed(1)}%` : undefined}
    >
      <span id="towerStartLabel" class="tower-start-label-wrap">
        <span class="tower-start-main">{snap.startMainLabel}</span>
        <span class="tower-start-sub">{snap.startSubLabel}</span>
        {#if snap.startShortfallLabel}
          <span class="tower-start-shortfall">{snap.startShortfallLabel}</span>
        {/if}
      </span>
    </button>

    {#if snap.batchVisible || snap.ascentMemoryVisible}
      <div class="tower-options-row">
        <TowerBatchContent />
        <TowerAscentMemoryContent />
      </div>
    {/if}

    <TowerRelicAutoContent />

    {#if snap.towerRecentRuns && snap.towerRecentRuns.length > 0}
      <div class="tower-recent-runs card">
        <div class="tower-recent-runs__header">
          <span class="tower-recent-runs__title">
            {snap.language === 'en' ? 'Recent Ascents' : 'Dernières ascensions'}
          </span>
          <span class="tower-recent-runs__hint">
            {snap.language === 'en' ? 'Last 5 runs' : '5 derniers runs'}
          </span>
        </div>
        <div class="tower-recent-runs__table" role="list">
          <div class="tower-recent-runs__head">
            <span>{snap.language === 'en' ? 'Floor' : 'Étage'}</span>
            <span>{snap.language === 'en' ? 'Marks' : 'Marques'}</span>
            <span>{snap.language === 'en' ? 'Duration' : 'Durée'}</span>
          </div>
          {#each snap.towerRecentRuns as run, idx (idx)}
            <div class="tower-recent-runs__row" role="listitem">
              <span class="tower-recent-runs__floor">
                {snap.language === 'en' ? 'Floor' : 'Étage'} <strong>{run.floor}</strong>
                {#if run.isRecord}
                  <span class="tower-recent-runs__record-badge" title={snap.language === 'en' ? 'New record' : 'Nouveau record'}>★</span>
                {/if}
              </span>
              <span class="tower-recent-runs__marks">
                <img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png" class="marque-triomphe-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">
                +{run.marks}
              </span>
              <span class="tower-recent-runs__duration">
                {run.durationFormatted}
              </span>
            </div>
          {/each}
        </div>
      </div>
    {/if}
  </div>
{/if}
