<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- batch panel from towerSnapshot */
  import { tower } from '../../stores/tower.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { bindTowerBatchPanelEvents } from '../../../towerSystem.js';

  let snap = $derived(tower.snapshot);
  let panelEl: HTMLDivElement | undefined = $state();

  $effect(() => {
    snap.batchHtml;
    const sig = snap.batchSig;
    const el = panelEl;
    const gm = game;
    if (!el || !sig || !gm) return;
    bindTowerBatchPanelEvents(el, gm);
  });
</script>

<div
  bind:this={panelEl}
  id="towerBatchPanel"
  class="tower-batch-panel card"
  style:display={snap.batchVisible ? '' : 'none'}
  aria-live="polite"
>
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  {@html snap.batchHtml}
</div>
