/**
 * Read-only move pill styling for UI previews (subway dex, etc.).
 */

import { coerceStr } from './coerceStr.ts';
import { TYPE_COLORS } from '../../constants/core.ts';
import { getMoveDefinition, resolveMoveName } from '../../constants/movesDb.ts';
import { localizeMoveName } from '../../constants/moveNameI18n.ts';
import type { GameRuntime } from '../types/game.js';

export interface MovePillDisplay {
    name: string;
    displayName: string;
    type: string;
    category: string;
    power: number;
    bg: string;
    text: string;
}

function getMoveTypeColors(moveTypeKey: string): { bg: string; text: string } {
    return (TYPE_COLORS as Record<string, { bg: string; text: string }>)[moveTypeKey]
        ?? { bg: '#868e96', text: '#fafafa' };
}

function resolveMoveDisplayName(game: GameRuntime | null | undefined, moveName: string): string {
    if (game && typeof game.getLocalizedMoveNamePlain === 'function') {
        return game.getLocalizedMoveNamePlain(moveName);
    }
    if (game && typeof game.getLocalizedMoveName === 'function') {
        const label = game.getLocalizedMoveName(moveName);
        if (label) return label;
    }
    return localizeMoveName(moveName, game?.language === 'en' ? 'en' : 'fr');
}

export function buildMovePillDisplay(
    game: GameRuntime | null | undefined,
    moveName: string,
): MovePillDisplay {
    const resolved = resolveMoveName(moveName);
    const moveDef = getMoveDefinition(resolved);
    const type = coerceStr(moveDef?.type, 'normal');
    const colors = getMoveTypeColors(type);
    return {
        name: resolved,
        displayName: resolveMoveDisplayName(game, resolved),
        type,
        category: coerceStr(moveDef?.category, 'physical'),
        power: Number(moveDef?.power ?? 0),
        bg: colors.bg,
        text: colors.text,
    };
}

const TYPE_LABELS_FR: Record<string, string> = {
  normal: 'Normal',
  fire: 'Feu',
  water: 'Eau',
  grass: 'Plante',
  electric: 'Électrik',
  ice: 'Glace',
  fighting: 'Combat',
  poison: 'Poison',
  ground: 'Sol',
  flying: 'Vol',
  psychic: 'Psy',
  bug: 'Insecte',
  rock: 'Roche',
  ghost: 'Spectre',
  dragon: 'Dragon',
  dark: 'Ténèbres',
  steel: 'Acier',
  fairy: 'Fée',
};

const TYPE_LABELS_EN: Record<string, string> = {
  normal: 'Normal',
  fire: 'Fire',
  water: 'Water',
  grass: 'Grass',
  electric: 'Electric',
  ice: 'Ice',
  fighting: 'Fighting',
  poison: 'Poison',
  ground: 'Ground',
  flying: 'Flying',
  psychic: 'Psychic',
  bug: 'Bug',
  rock: 'Rock',
  ghost: 'Ghost',
  dragon: 'Dragon',
  dark: 'Dark',
  steel: 'Steel',
  fairy: 'Fairy',
};

export function formatPokemonTypeLabel(typeKey: string, lang: string = 'fr'): string {
  const key = String(typeKey || 'normal').toLowerCase();
  const isEn = String(lang || 'fr').toLowerCase().startsWith('en');
  return (isEn ? TYPE_LABELS_EN[key] : TYPE_LABELS_FR[key]) ?? typeKey;
}

export function formatMoveCategoryLabel(category: string, lang: string = 'fr'): string {
  const cat = String(category || 'physical').toLowerCase();
  const isEn = String(lang || 'fr').toLowerCase().startsWith('en');
  if (cat === 'special') return isEn ? 'Special' : 'Spécial';
  if (cat === 'status') return isEn ? 'Status' : 'Statut';
  return isEn ? 'Physical' : 'Physique';
}

