<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { SubwayPokemonPreview } from '../../lib/subwayTrainerPreview.ts';
  import type { SubwayTrainerPreview } from '../../lib/subwayTrainerPreview.ts';
  import type { GameRuntime } from '../../types/game.js';
  import { getMoveDefinition } from '../../../constants/movesDb.ts';
  import { getMoveBaseAccuracy } from '../../lib/resolveMoveHit.ts';
  import { uiText } from '../../ui/i18n.ts';
  import { formatNumber } from '../../../formatters.js';
  import { formatPokemonTypeLabel, formatMoveCategoryLabel } from '../../lib/movePillDisplay.ts';

  let {
    trainer,
    pokemon,
    lang = 'fr',
  }: {
    trainer: SubwayTrainerPreview;
    pokemon: SubwayPokemonPreview;
    lang?: string;
  } = $props();

  const STAT_CONFIGS = [
    { key: 'hp' as const, label: 'HP', color: '#ef4444' },
    { key: 'attack' as const, label: 'ATK', color: '#fb923c' },
    { key: 'defense' as const, label: 'DEF', color: '#4cc46a' },
    { key: 'spAttack' as const, label: 'ATK SP', color: '#f472b6' },
    { key: 'spDefense' as const, label: 'DEF SP', color: '#2dd4bf' },
    { key: 'speed' as const, label: 'SPD', color: '#c084fc' },
  ];

  const ultStatus = $derived.by(() => {
    if (pokemon.canUseUltimate) {
      return uiText('subway.ultimatesEnabled', 'Peut utiliser son ultime');
    }
    return uiText('subway.ultimatesBlockedItem', 'Ultime bloqué par l\'objet tenu');
  });

  function powerShortLabel(): string {
    const gm = game as GameRuntime | null;
    if (gm?.t) {
      const out = gm.t('modal.creature.powerShort');
      if (out && out !== 'modal.creature.powerShort') return out;
    }
    return 'Puis.';
  }

  function moveAccuracyLabel(moveName: string): string {
    const def = getMoveDefinition(moveName) as Record<string, unknown> | undefined;
    if (!def) return '100 %';
    if (def.accuracy === null) return '—';
    if (def.accuracy === undefined) return '100 %';
    const base = getMoveBaseAccuracy(def);
    return base != null ? `${base} %` : '—';
  }
</script>

<article class="tower-subway-pokemon-detail">
  <!-- Méta compacte optionnelle si double type ou objet tenu -->
  {#if pokemon.secondaryType || pokemon.heldItem}
    <div class="tower-subway-detail-meta-strip">
      <div class="tower-subway-detail-types">
        <span class="type-badge type-{pokemon.primaryType}">
          {formatPokemonTypeLabel(pokemon.primaryType, lang)}
        </span>
        {#if pokemon.secondaryType}
          <span class="type-badge type-{pokemon.secondaryType}">
            {formatPokemonTypeLabel(pokemon.secondaryType, lang)}
          </span>
        {/if}
      </div>
      {#if pokemon.heldItem}
        <div class="tower-subway-detail-item-hint" title={pokemon.heldItem.description}>
          <span class="tower-subway-detail-item-label">Objet :</span>
          <strong class="tower-subway-detail-item-name">{pokemon.heldItem.name}</strong>
        </div>
      {/if}
    </div>
  {/if}

  <!-- Section 1 : Attaques en tableau propre à liseré coloré de type -->
  <section class="tower-subway-detail-section tower-subway-moves-section">
    <div class="tower-subway-moves-header">
      <span class="tower-subway-col-move">{uiText('subway.movesLabel', 'Attaques')}</span>
      <span class="tower-subway-col-cat">Cat.</span>
      <span class="tower-subway-col-pow">{powerShortLabel()}</span>
      <span class="tower-subway-col-acc">Préc.</span>
    </div>
    <div class="tower-subway-moves-list">
      {#each pokemon.moves as move (move.name)}
        {@const catKey = move.category === 'special' ? 'special' : (move.category === 'status' ? 'status' : 'physical')}
        <div
          class="tower-subway-move-row creature-move-row"
          data-move-tooltip-name={move.name}
          style="border-left: 4px solid {move.bg};"
        >
          <div class="tower-subway-move-name-wrap">
            <span class="tower-subway-move-name">{move.displayName}</span>
          </div>
          <div class="tower-subway-move-cat-wrap">
            <span class="tower-subway-cat-badge cat-{catKey}">
              {formatMoveCategoryLabel(move.category, lang)}
            </span>
          </div>
          <div class="tower-subway-move-pow">
            {move.power > 0 ? move.power : '—'}
          </div>
          <div class="tower-subway-move-acc">
            {moveAccuracyLabel(move.name)}
          </div>
        </div>
      {/each}
    </div>
  </section>

  <!-- Section 2 : Talent & Ultime côte à côte ou empilés de façon cohérente -->
  <div class="tower-subway-abilities-container">
    {#if pokemon.talent}
      <section class="tower-subway-ability-card tower-subway-talent-card">
        <div class="tower-subway-ability-card__title">
          <span class="tower-subway-ability-badge talent-badge">{uiText('subway.talentLabel', 'Talent')}</span>
          <strong>{pokemon.talent.name}</strong>
        </div>
        <p class="tower-subway-ability-card__desc">{pokemon.talent.description}</p>
      </section>
    {/if}

    <section class="tower-subway-ability-card tower-subway-ultimate-card">
      <div class="tower-subway-ability-card__header">
        <div class="tower-subway-ability-card__title">
          <span class="tower-subway-ability-badge ult-badge">{uiText('subway.ultimateLabel', 'Ultime')}</span>
          <strong>{pokemon.ultimate.name} <span class="tower-subway-ult-cost">({pokemon.ultimate.chargeNeeded})</span></strong>
        </div>
        <span class="tower-subway-ult-pill" class:is-on={pokemon.canUseUltimate}>
          {ultStatus}
        </span>
      </div>
      <p class="tower-subway-ability-card__desc">{pokemon.ultimate.description}</p>
    </section>
  </div>

  <!-- Section 3 : Stats indicatives colorées sans deux-points -->
  <section class="tower-subway-detail-section tower-subway-stats-section">
    <h5 class="tower-subway-section-label">{uiText('subway.statsLabel', 'Stats indicatives')}</h5>
    <div class="tower-subway-stats-grid">
      {#each STAT_CONFIGS as row (row.key)}
        <div class="tower-subway-stat-card" style="border-bottom: 2px solid {row.color};">
          <span class="tower-subway-stat-card__label" style="color: {row.color};">{row.label}</span>
          <strong class="tower-subway-stat-card__val">{formatNumber(pokemon.indicativeStats[row.key])}</strong>
        </div>
      {/each}
    </div>
  </section>
</article>
