<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- relic auto panel from towerSnapshot */
  import { tower } from '../../stores/tower.svelte.ts';
  import { game } from '../../../gameManager.js';
  import { bindTowerRelicAutoPanelEvents } from '../../../towerSystem.js';

  let snap = $derived(tower.snapshot);
  let panelEl: HTMLDivElement | undefined = $state();

  $effect(() => {
    snap.relicAutoHtml;
    const sig = snap.relicAutoSig;
    const el = panelEl;
    const gm = game;
    if (!el || !sig || !gm) return;
    bindTowerRelicAutoPanelEvents(el, gm);
  });
</script>

<div
  bind:this={panelEl}
  id="towerRelicAutoPanel"
  class="tower-relic-auto-panel card"
  style:display={snap.relicAutoVisible ? '' : 'none'}
  aria-live="polite"
>
  <!-- svelte-ignore a11y_no_static_element_interactions -->
  {@html snap.relicAutoHtml}
</div>
