<script lang="ts">
  import { game } from '../../../gameManager.js';
  import type { GameRuntime } from '../../types/game.js';
  import { tower } from '../../stores/tower.svelte.ts';
  import { buildSubwayTrainerPreviewsForToday } from '../../lib/subwayTrainerPreview.ts';
  import { useGameLanguageTick } from '../../lib/useGameLanguageTick.svelte.ts';
  import { formatPokemonTypeLabel } from '../../lib/movePillDisplay.ts';
  import SubwayOpponentPokemonCard from './SubwayOpponentPokemonCard.svelte';
  import SubwayOpponentPokemonDetail from './SubwayOpponentPokemonDetail.svelte';

  const { trackGameLanguage } = useGameLanguageTick();
  let snap = $derived(tower.snapshot);

  let selectedTrainerIndex = $state(0);
  let selectedPokemonIndex = $state(0);

  const dailyPreview = $derived.by(() => {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm) return null;
    return buildSubwayTrainerPreviewsForToday(gm);
  });

  const previews = $derived(dailyPreview?.trainers ?? []);

  const selectedTrainer = $derived(previews[selectedTrainerIndex] ?? null);
  const selectedPokemon = $derived(selectedTrainer?.team[selectedPokemonIndex] ?? null);

  function t(key: string, fallback: string, vars?: Record<string, string | number>): string {
    trackGameLanguage();
    const gm = game as GameRuntime | null;
    if (!gm?.t) return applyVars(fallback, vars);
    const out = gm.t(key, vars);
    return out && out !== key ? out : applyVars(fallback, vars);
  }

  function applyVars(template: string, vars?: Record<string, string | number>): string {
    if (!vars) return template;
    return template.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''));
  }

  function selectTrainer(index: number) {
    selectedTrainerIndex = index;
    selectedPokemonIndex = 0;
  }
</script>

{#if previews.length > 0}
  <div class="tower-subway-trainer-dex">
    <div class="tower-subway-trainer-dex__header">
      <h4 id="subwayTrainerDexTitle" class="tower-subway-trainer-dex__title">
        {t('subway.trainerDexTitle', 'Dresseurs du wagon')}
      </h4>
      <p class="tower-subway-trainer-dex__hint">
        {t('subway.trainerDexHint', 'Cliquez un dresseur, puis un Pokémon pour voir ses attaques.')}
      </p>
    </div>

    <!-- 7 Dresseurs sur une seule rangée sans scroll -->
    <div
      class="tower-subway-trainer-grid"
      role="tablist"
      aria-label={t('subway.trainerDexTitle', 'Dresseurs du wagon')}
    >
      {#each previews as trainer, idx (trainer.id)}
        {@const isDefeated = snap.subwayActive && trainer.battleIndex <= snap.subwayWinsThisRun}
        {@const isSelected = selectedTrainerIndex === idx}
        <button
          type="button"
          role="tab"
          class="tower-subway-trainer-chip"
          class:active={isSelected}
          class:is-defeated={isDefeated}
          aria-selected={isSelected}
          title={`Dresseur #${trainer.battleIndex} — ${trainer.name}${trainer.useUltimates ? ' · ⚡ Utilise son ultime en combat' : ''}${isDefeated ? ' · ✓ Vaincu' : ''}`}
          onclick={() => selectTrainer(idx)}
        >
          <img
            src={trainer.spriteUrl}
            alt=""
            class="tower-subway-trainer-sprite"
            onerror={(e) => { (e.currentTarget as HTMLImageElement).style.display = 'none'; }}
          />
          <div class="tower-subway-trainer-chip__meta">
            <span class="tower-subway-trainer-num">#{trainer.battleIndex}</span>
            {#if isDefeated}
              <span class="tower-subway-trainer-check" title="Vaincu">✓</span>
            {/if}
            {#if trainer.useUltimates}
              <span class="tower-subway-trainer-ult" title={t('subway.ultimatesEnabled', 'Peut utiliser son ultime')}>⚡</span>
            {/if}
          </div>
        </button>
      {/each}
    </div>

    <!-- Mini-légende explicite pour les éclairs des dresseurs 5, 6, 7 -->
    <div class="tower-subway-trainer-legend">
      <span class="tower-subway-legend-item" title="Les dresseurs 5, 6 et 7 peuvent déclencher leurs attaques ultimes">
        <span class="tower-subway-trainer-ult" aria-hidden="true">⚡</span>
        <span class="tower-subway-legend-text">
          {snap.language === 'en' ? 'Trainers #5–#7: Ultimates enabled' : 'Dresseurs #5–#7 : Ultimes actifs'}
        </span>
      </span>
    </div>

    {#if selectedTrainer}
      <div class="tower-subway-trainer-panel" role="tabpanel">
        <div class="tower-subway-trainer-panel__header">
          <div class="tower-subway-trainer-panel__identity">
            <strong class="tower-subway-trainer-panel__name">
              Dresseur #{selectedTrainer.battleIndex} — {selectedTrainer.name}
            </strong>
            <span class="type-badge type-{selectedTrainer.specialtyType}">
              {formatPokemonTypeLabel(selectedTrainer.specialtyType, snap.language)}
            </span>
            {#if selectedTrainer.useUltimates}
              <span class="tower-subway-ult-badge tower-subway-ult-badge--on" title="Ce dresseur peut déclencher la capacité ultime de ses Pokémon en combat">⚡ Utilise son ultime</span>
            {/if}
          </div>
        </div>

        <h5 class="tower-subway-team-label">{t('subway.teamLabel', 'Équipe')}</h5>
        <div class="tower-subway-team-grid">
          {#each selectedTrainer.team as mon, pIdx (mon.name)}
            <SubwayOpponentPokemonCard
              pokemon={mon}
              selected={selectedPokemonIndex === pIdx}
              lang={snap.language}
              onclick={() => { selectedPokemonIndex = pIdx; }}
            />
          {/each}
        </div>

        {#if selectedPokemon}
          <SubwayOpponentPokemonDetail
            trainer={selectedTrainer}
            pokemon={selectedPokemon}
            lang={snap.language}
          />
        {/if}
      </div>
    {/if}
  </div>
{/if}
